import { FormEvent, ReactNode, useEffect, useMemo, useState } from 'react';
import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Navigate, NavLink, Route, Routes, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import DOMPurify from 'dompurify';
import { marked } from 'marked';
import { api, ApiError, Flow, mutation, Page as ApiPage, Project, setCsrfToken, Task, User, WorkflowState, Workspace } from './api';

type Session = { user: User; csrfToken: string };
const nav = [{ to: 'tasks', label: 'Tasks', mark: 'T' }, { to: 'projects', label: 'Projects', mark: 'P' }, { to: 'flows', label: 'Flows', mark: 'F' }, { to: 'reviews', label: 'Reviews', mark: 'R' }, { to: 'inbox', label: 'Inbox', mark: '●' }, { to: 'github', label: 'GitHub', mark: 'GH' }, { to: 'search', label: 'Search', mark: '⌕' }];

function App() {
  const session = useQuery<Session>({ queryKey: ['session'], queryFn: () => api('/auth/me'), retry: false });
  useEffect(() => { if (session.data?.csrfToken) setCsrfToken(session.data.csrfToken); }, [session.data]);
  if (session.isLoading) return <Loading />;
  if (!session.data) return <Access />;
  return <AuthedApp session={session.data} />;
}

function Access() {
  const setup = useQuery<{ initialized: boolean }>({ queryKey: ['setup-status'], queryFn: () => api('/auth/setup-status') });
  if (setup.isLoading) return <Loading />;
  return <main className="access"><section className="access-card"><Brand /><h1>{setup.data?.initialized ? 'Welcome back' : 'Set up your control room'}</h1><p>{setup.data?.initialized ? 'Sign in to continue where the work is.' : 'Create the first administrator and workspace.'}</p>{setup.data?.initialized ? <Login /> : <Setup />}</section></main>;
}

function OAuthConsent() {
  const [params] = useSearchParams(); const requestId = params.get('request') ?? '';
  const request = useQuery<any>({ queryKey: ['oauth-request', requestId], queryFn: () => api(`/oauth/requests/${requestId}`), enabled: Boolean(requestId), retry: false });
  const [workspaceIds, setWorkspaceIds] = useState<string[]>([]);
  useEffect(() => { if (request.data) setWorkspaceIds(request.data.workspaces.map((workspace: Workspace) => workspace.id)); }, [request.data]);
  const decide = useMutation({ mutationFn: (approve: boolean) => api<{ redirectUri: string }>(`/oauth/requests/${requestId}/decision`, mutation('POST', { approve, workspaceIds: approve ? workspaceIds : [] })), onSuccess: ({ redirectUri }) => window.location.assign(redirectUri) });
  if (!requestId) return <Navigate to="/" replace />;
  if (request.isLoading) return <Loading />;
  if (!request.data) return <main className="access"><section className="access-card"><Brand /><h1>Authorization request unavailable</h1><p>This OAuth request is invalid or has expired. Return to your MCP client and start again.</p></section></main>;
  const toggle = (id: string) => setWorkspaceIds((current) => current.includes(id) ? current.filter((value) => value !== id) : [...current, id]);
  return <main className="access"><section className="access-card"><Brand /><h1>Connect {request.data.client.name}</h1><p>It requests access to Anklav via the MCP endpoint.</p><div className="stack"><p><strong>Scopes:</strong> {request.data.scopes.join(', ')}</p><p><strong>Redirect:</strong> {request.data.redirectUri}</p><label className="field"><span>Workspaces</span>{request.data.workspaces.map((workspace: Workspace) => <span key={workspace.id}><input type="checkbox" checked={workspaceIds.includes(workspace.id)} onChange={() => toggle(workspace.id)} /> {workspace.name}</span>)}</label><Error text={decide.error instanceof Error ? decide.error.message : ''} /><button className="button primary" disabled={!workspaceIds.length || decide.isPending} onClick={() => decide.mutate(true)}>Authorize</button><button className="button ghost" disabled={decide.isPending} onClick={() => decide.mutate(false)}>Cancel</button></div></section></main>;
}

function Login() {
  const client = useQueryClient(); const [error, setError] = useState('');
  const action = useMutation({ mutationFn: (body: any) => api<Session>('/auth/login', mutation('POST', body)), onSuccess: (data) => { setCsrfToken(data.csrfToken); client.setQueryData(['session'], data); }, onError: (err: ApiError) => setError(err.message) });
  return <form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); action.mutate({ email: form.get('email'), password: form.get('password') }); }} className="stack"><Field label="Email" name="email" type="email" required autoComplete="email" /><Field label="Password" name="password" type="password" required autoComplete="current-password" /><Error text={error} /><button className="button primary" disabled={action.isPending}>{action.isPending ? 'Signing in…' : 'Sign in'}</button></form>;
}

function Setup() {
  const client = useQueryClient(); const [error, setError] = useState('');
  const action = useMutation({ mutationFn: (body: any) => api<Session>('/auth/setup', mutation('POST', body)), onSuccess: (data) => { setCsrfToken(data.csrfToken); client.setQueryData(['session'], data); }, onError: (err: ApiError) => setError(err.message) });
  return <form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); action.mutate(Object.fromEntries(form)); }} className="stack"><Field label="Your name" name="displayName" required /><Field label="Email" name="email" type="email" required /><Field label="Password" name="password" type="password" required minLength={12} /><Field label="First workspace" name="workspaceName" required /><Field label="Setup token" name="setupToken" type="password" required /><Error text={error} /><button className="button primary" disabled={action.isPending}>{action.isPending ? 'Creating…' : 'Create Anklav'}</button></form>;
}

function AuthedApp({ session }: { session: Session }) {
  const workspaces = useQuery<Workspace[]>({ queryKey: ['workspaces'], queryFn: () => api('/workspaces'), refetchInterval: 15_000 });
  const savedTheme = localStorage.getItem('anklav-theme');
  const initialTheme = session.user.theme ?? (savedTheme === 'light' || savedTheme === 'dark' || savedTheme === 'system' ? savedTheme : 'system');
  const [theme, setTheme] = useState<'system' | 'light' | 'dark'>(initialTheme);
  const saveTheme = useMutation({ mutationFn: (next: string) => api<{ user: User }>('/auth/preferences', mutation('PATCH', { theme: next })), onSuccess: (next) => { setTheme(next.user.theme); localStorage.setItem('anklav-theme', next.user.theme); } });
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('anklav-theme', theme); }, [theme]);
  if (workspaces.isLoading) return <Loading />;
  if (!workspaces.data?.length) return <CreateFirstWorkspace />;
  return <Routes>
    <Route path="/oauth/consent" element={<OAuthConsent />} />
    <Route path="/" element={<Navigate to={`/w/${workspaces.data[0]!.id}/tasks`} replace />} />
    <Route path="/w/:workspaceId/*" element={<WorkspaceShell session={session} workspaces={workspaces.data} theme={theme} setTheme={(next) => { setTheme(next); saveTheme.mutate(next); }} />} />
    <Route path="*" element={<Navigate to={`/w/${workspaces.data[0]!.id}/tasks`} replace />} />
  </Routes>;
}

function CreateFirstWorkspace() {
  const client = useQueryClient(); const [name, setName] = useState('');
  const create = useMutation({ mutationFn: () => api('/workspaces', mutation('POST', { name })), onSuccess: () => client.invalidateQueries({ queryKey: ['workspaces'] }) });
  return <main className="access"><section className="access-card"><Brand /><h1>Create a workspace</h1><p>Workspaces are your isolated portfolios. You will be its first owner.</p><form className="stack" onSubmit={(event) => { event.preventDefault(); create.mutate(); }}><Field label="Workspace name" value={name} onChange={setName} /><button className="button primary">Create workspace</button></form></section></main>;
}

function WorkspaceShell({ session, workspaces, theme, setTheme }: { session: Session; workspaces: Workspace[]; theme: 'system' | 'light' | 'dark'; setTheme: (next: 'system' | 'light' | 'dark') => void }) {
  const { workspaceId = '' } = useParams(); const navigate = useNavigate(); const current = workspaces.find((workspace) => workspace.id === workspaceId) ?? workspaces[0]!;
  const unread = useQuery<{ unread: number }>({ queryKey: ['github-notification-count', current.id], queryFn: () => api(`/workspaces/${current.id}/github/notifications/unread-count`), refetchInterval: 15_000, retry: false });
  if (current.id !== workspaceId) return <Navigate to={`/w/${current.id}/tasks`} replace />;
  return <div className="app-shell"><aside className="sidebar"><Brand compact /><label className="workspace-select"><span>Workspace</span><select value={current.id} onChange={(event) => navigate(`/w/${event.target.value}/tasks`)}>{workspaces.map((workspace) => <option key={workspace.id} value={workspace.id}>{workspace.name}</option>)}</select></label><nav>{nav.map((item) => <NavLink key={item.to} to={`/w/${current.id}/${item.to}`} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}><b>{item.mark}</b>{item.label}{item.to === 'inbox' && unread.data?.unread ? <span className="nav-badge">{unread.data.unread > 99 ? '99+' : unread.data.unread}</span> : null}</NavLink>)}<NavLink to={`/w/${current.id}/settings`} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}><b>⚙</b>Settings</NavLink></nav><div className="sidebar-footer"><button className="text-button" onClick={() => setTheme(theme === 'dark' ? 'light' : theme === 'light' ? 'system' : 'dark')}>Theme: {theme}</button><span>{session.user.displayName}</span></div></aside><main className="workspace-main"><OfflineNotice /><ChangePoller workspaceId={current.id} /><Routes><Route path="tasks/:taskId?" element={<TasksPage workspace={current} />} /><Route path="projects/:projectId?" element={<ProjectsPage workspace={current} />} /><Route path="flows/:flowId?" element={<FlowsPage workspace={current} />} /><Route path="reviews/:pullRequestId?" element={<ReviewsPage workspace={current} />} /><Route path="inbox" element={<InboxPage workspace={current} />} /><Route path="github" element={<Page heading="GitHub" subheading="Connect repositories, issue sync, and review workflows."><GitHubSettings workspace={current} /></Page>} /><Route path="search" element={<SearchPage workspace={current} />} /><Route path="settings/*" element={<SettingsPage workspace={current} session={session} />} /><Route path="*" element={<Navigate to="tasks" replace />} /></Routes></main></div>;
}

function OfflineNotice() {
  const [online, setOnline] = useState(navigator.onLine);
  useEffect(() => { const update = () => setOnline(navigator.onLine); window.addEventListener('online', update); window.addEventListener('offline', update); return () => { window.removeEventListener('online', update); window.removeEventListener('offline', update); }; }, []);
  return online ? null : <div className="offline-notice" role="status">You’re offline. The app shell is available, but work data and changes need a connection.</div>;
}

function ChangePoller({ workspaceId }: { workspaceId: string }) {
  const client = useQueryClient(); const [after, setAfter] = useState(() => Number(sessionStorage.getItem(`anklav-sequence-${workspaceId}`) ?? 0));
  const changes = useQuery<any[]>({ queryKey: ['changes', workspaceId, after], queryFn: () => api(`/workspaces/${workspaceId}/changes?after=${after}`), refetchInterval: 15_000, retry: false });
  useEffect(() => { if (!changes.data?.length) return; const next = Math.max(...changes.data.map((entry) => Number(entry.sequence))); sessionStorage.setItem(`anklav-sequence-${workspaceId}`, String(next)); setAfter(next); client.invalidateQueries({ predicate: (query) => Array.isArray(query.queryKey) && query.queryKey.includes(workspaceId) && query.queryKey[0] !== 'changes' }); }, [changes.data, client, workspaceId]);
  return null;
}

function useCursorList<T>(key: unknown[], path: string, params: Record<string, string>) {
  const query = new URLSearchParams(Object.entries(params).filter(([, value]) => value));
  const result = useInfiniteQuery({
    queryKey: [...key, params],
    initialPageParam: '',
    queryFn: ({ pageParam }) => {
      const next = new URLSearchParams(query);
      if (pageParam) next.set('cursor', pageParam as string);
      return api<ApiPage<T>>(`${path}?${next.toString()}`);
    },
    getNextPageParam: (last) => last.nextCursor ?? undefined,
    refetchInterval: 15_000,
  });
  return { ...result, items: result.data?.pages.flatMap((page) => page.items) ?? [] };
}

function TasksPage({ workspace }: { workspace: Workspace }) {
  const { taskId } = useParams(); const navigate = useNavigate(); const [filters, setFilters] = useState({ q: '', projectId: '', flowId: '', stateId: '', priority: '', assigneeMembershipId: '', labelId: '' });
  const tasks = useCursorList<any>(['tasks', workspace.id], `/workspaces/${workspace.id}/tasks`, filters);
  const projects = useQuery<ApiPage<Project>>({ queryKey: ['project-options', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/projects?limit=100`) });
  const states = useQuery<WorkflowState[]>({ queryKey: ['states', workspace.id, 'task'], queryFn: () => api(`/workspaces/${workspace.id}/workflows?entity=task`) });
  const flows = useQuery<ApiPage<any>>({ queryKey: ['flow-options', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/flows?limit=100`) });
  const members = useQuery<any[]>({ queryKey: ['members', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/members`) });
  const labels = useQuery<any[]>({ queryKey: ['labels', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/labels`) });
  const setFilter = (name: keyof typeof filters, value: string) => setFilters((current) => ({ ...current, [name]: value }));
  return <Page heading="Tasks" subheading="Bounded work with a clear technical home." action={<CreateTask workspace={workspace} projects={projects.data?.items ?? []} states={states.data ?? []} />}><div className="content-grid"><section className="list-panel"><input className="search" placeholder="Search tasks" value={filters.q} onChange={(event) => setFilter('q', event.target.value)} /><div className="filter-grid"><select aria-label="Filter by project" value={filters.projectId} onChange={(event) => setFilter('projectId', event.target.value)}><option value="">All projects</option>{projects.data?.items.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><select aria-label="Filter by flow" value={filters.flowId} onChange={(event) => setFilter('flowId', event.target.value)}><option value="">All flows</option>{flows.data?.items.map(({ flow }) => <option key={flow.id} value={flow.id}>{flow.name}</option>)}</select><select aria-label="Filter by task state" value={filters.stateId} onChange={(event) => setFilter('stateId', event.target.value)}><option value="">All states</option>{states.data?.map((state) => <option key={state.id} value={state.id}>{state.name}</option>)}</select><select aria-label="Filter by priority" value={filters.priority} onChange={(event) => setFilter('priority', event.target.value)}><option value="">All priorities</option>{priorityOptions()}</select><select aria-label="Filter by assignee" value={filters.assigneeMembershipId} onChange={(event) => setFilter('assigneeMembershipId', event.target.value)}><option value="">Anyone</option>{members.data?.filter((member) => member.active).map((member) => <option key={member.id} value={member.id}>{member.displayName}</option>)}</select><select aria-label="Filter by label" value={filters.labelId} onChange={(event) => setFilter('labelId', event.target.value)}><option value="">All labels</option>{labels.data?.map((label) => <option key={label.id} value={label.id}>{label.name}</option>)}</select></div>{tasks.isLoading ? <Loading /> : <div className="table-list">{tasks.items.map((row) => <button key={row.task.id} onClick={() => navigate(`/w/${workspace.id}/tasks/${row.task.identifier ?? row.task.id}`)} className={`row-button ${taskId === row.task.id || taskId === row.task.identifier ? 'selected' : ''}`}><Status state={row.state} /><span className="row-main"><strong>{row.task.title}</strong><small>{row.task.identifier} · {row.project.name} · {row.task.priority}</small></span><time>{relativeTime(row.task.updatedAt)}</time></button>)}</div>}{!tasks.items.length && !tasks.isLoading && <Empty title="No matching tasks" text="Adjust filters or capture the next bounded piece of work." />}{tasks.hasNextPage && <button className="button load-more" onClick={() => tasks.fetchNextPage()} disabled={tasks.isFetchingNextPage}>{tasks.isFetchingNextPage ? 'Loading…' : 'Load more'}</button>}</section><section className="detail-panel">{taskId ? <TaskDetail workspace={workspace} taskId={taskId} states={states.data ?? []} /> : <Hint title="Choose a task" text="Open a task to see its purpose, criteria, evidence, and history." />}</section></div></Page>;
}

function CreateTask({ workspace, projects, states }: { workspace: Workspace; projects: Project[]; states: WorkflowState[] }) {
  const client = useQueryClient(); const [open, setOpen] = useState(false); const [title, setTitle] = useState(''); const [projectId, setProjectId] = useState(projects[0]?.id ?? '');
  useEffect(() => { if (!projectId && projects[0]) setProjectId(projects[0].id); }, [projectId, projects]);
  const action = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/tasks`, mutation('POST', { title, projectId, workflowStateId: states.find((state) => state.isInitial)?.id })), onSuccess: () => { client.invalidateQueries({ queryKey: ['tasks', workspace.id] }); setOpen(false); setTitle(''); } });
  if (!open) return <button className="button primary" disabled={!projects.length} onClick={() => setOpen(true)}>New task</button>;
  return <InlineForm onCancel={() => setOpen(false)} onSubmit={() => action.mutate()} pending={action.isPending}><Field label="Title" value={title} onChange={setTitle} autoFocus /><label>Project<select value={projectId} onChange={(event) => setProjectId(event.target.value)}>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><Error text={action.error instanceof Error ? action.error.message : ''} /></InlineForm>;
}

function TaskDetail({ workspace, taskId, states }: { workspace: Workspace; taskId: string; states: WorkflowState[] }) {
  const client = useQueryClient();
  const detail = useQuery<any>({ queryKey: ['task', workspace.id, taskId], queryFn: () => api(`/workspaces/${workspace.id}/tasks/${taskId}`), refetchInterval: 15_000 });
  const [comment, setComment] = useState('');
  const refresh = () => { client.invalidateQueries({ queryKey: ['task', workspace.id, taskId] }); client.invalidateQueries({ queryKey: ['tasks', workspace.id] }); };
  const update = useMutation({ mutationFn: (body: any) => api(`/workspaces/${workspace.id}/tasks/${taskId}`, mutation('PATCH', body, detail.data.version)), onSuccess: refresh, onError: (err: ApiError) => err.status === 412 && refresh() });
  const review = useMutation({ mutationFn: (reviewStatus: string) => api(`/workspaces/${workspace.id}/tasks/${taskId}/review`, mutation('PATCH', { reviewStatus }, detail.data.version)), onSuccess: refresh });
  const commentAction = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/task/${taskId}/comments`, mutation('POST', { body: comment })), onSuccess: () => { setComment(''); refresh(); } });
  if (detail.isLoading) return <Loading />;
  if (!detail.data) return <Empty title="Task not found" text="It may have been deleted or moved." />;
  const task = detail.data;
  const chooseState = async (workflowStateId: string) => {
    const preview = await api<{ warnings: string[] }>(`/workspaces/${workspace.id}/tasks/${taskId}/transition-preview?stateId=${workflowStateId}`);
    if (!preview.warnings.length || window.confirm(`This transition has advisory signals:\n\n${preview.warnings.join('\n')}\n\nContinue?`)) update.mutate({ workflowStateId });
  };
  return <article className="detail">
    <header className="detail-header"><div><span className="eyebrow">{task.identifier} · {task.project?.name}</span><h2>{task.title}</h2></div><select aria-label="Task state" value={task.workflowStateId} onChange={(event) => void chooseState(event.target.value)}>{states.map((state) => <option key={state.id} value={state.id}>{state.name}</option>)}</select></header>
    <TaskGitHub workspace={workspace} task={task} />
    {task.transitionWarnings?.length > 0 && <Callout title="Transition signals">{task.transitionWarnings.map((warning: string) => <p key={warning}>{warning}</p>)}</Callout>}
    <EditableMarkdown title="Goal and scope" value={task.description} onSave={(description) => update.mutate({ description })} />
    <section className="meta-grid"><Meta label="Priority" value={task.priority} />{task.humanReviewRequired ? <label>Human review<select value={task.reviewStatus} onChange={(event) => review.mutate(event.target.value)}><option value="pending">pending</option><option value="approved">approved</option><option value="changes_requested">changes requested</option></select></label> : <Meta label="Human review" value="Not required" />}<Meta label="Due" value={task.dueDate ?? '—'} /></section>
    <TaskProperties workspace={workspace} task={task} save={(body) => update.mutate(body)} />
    <Checklist workspace={workspace} task={task} />
    <EditableMarkdown title="Verification performed" value={task.verificationPerformed} empty="Record the verification you performed." onSave={(verificationPerformed) => update.mutate({ verificationPerformed })} />
    <EditableMarkdown title="Completion evidence" value={task.completionEvidence} empty="Record completion evidence." onSave={(completionEvidence) => update.mutate({ completionEvidence })} />
    <EditableMarkdown title="Remaining limitations" value={task.remainingLimitations} empty="Record known limitations." onSave={(remainingLimitations) => update.mutate({ remainingLimitations })} />
    <EditableMarkdown title="Follow-up work" value={task.followUpWork} empty="Record follow-up work." onSave={(followUpWork) => update.mutate({ followUpWork })} />
    <section><h3>Flows</h3>{task.flows?.length ? task.flows.map((entry: any) => <span className="chip" key={entry.flow.id}>{entry.link.role}: {entry.flow.name}</span>) : <p className="muted">Not connected to a flow.</p>}</section>
    <LabelEditor workspace={workspace} subject="task" subjectId={task.id} assigned={task.labels ?? []} />
    <RelationEditor workspace={workspace} kind="task" subjectId={task.id} relations={task.relations ?? []} />
    <section><h3>Discussion</h3><div className="comments">{task.comments?.map((entry: any) => <article key={entry.id} className="comment"><Markdown value={entry.body} /><small>{relativeTime(entry.createdAt)}</small></article>)}</div><textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Add progress, evidence, or a question…" /><button className="button" disabled={!comment.trim() || commentAction.isPending} onClick={() => commentAction.mutate()}>Add comment</button></section>
    <Activity events={task.activity ?? []} />
  </article>;
}

function Checklist({ workspace, task }: { workspace: Workspace; task: any }) {
  const client = useQueryClient(); const [text, setText] = useState(''); const [kind, setKind] = useState<'readiness' | 'acceptance'>('acceptance');
  const add = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/tasks/${task.id}/checklists`, mutation('POST', { text, kind })), onSuccess: () => { setText(''); client.invalidateQueries({ queryKey: ['task', workspace.id, task.id] }); } });
  const toggle = useMutation({ mutationFn: (item: any) => api(`/workspaces/${workspace.id}/checklists/${item.id}`, mutation('PATCH', { completed: !item.completed })), onSuccess: () => client.invalidateQueries({ queryKey: ['task', workspace.id, task.id] }) });
  return <section><h3>Criteria</h3>{['readiness', 'acceptance'].map((group) => <div className="criteria" key={group}><h4>{group === 'readiness' ? 'Readiness' : 'Acceptance'}</h4>{task.checklists?.filter((item: any) => item.kind === group).map((item: any) => <label className="check" key={item.id}><input type="checkbox" checked={item.completed} onChange={() => toggle.mutate(item)} />{item.text}</label>)}</div>)}<div className="inline-fields"><select value={kind} onChange={(event) => setKind(event.target.value as any)}><option value="acceptance">Acceptance</option><option value="readiness">Readiness</option></select><input value={text} onChange={(event) => setText(event.target.value)} placeholder="Add criterion" /><button className="button" onClick={() => add.mutate()} disabled={!text.trim()}>Add</button></div></section>;
}

function LabelEditor({ workspace, subject, subjectId, assigned }: { workspace: Workspace; subject: 'project' | 'flow' | 'task'; subjectId: string; assigned: any[] }) {
  const client = useQueryClient(); const labels = useQuery<any[]>({ queryKey: ['labels', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/labels`) }); const [labelId, setLabelId] = useState('');
  const changed = () => { client.invalidateQueries({ queryKey: [subject, workspace.id, subjectId] }); client.invalidateQueries({ queryKey: ['tasks', workspace.id] }); client.invalidateQueries({ queryKey: ['projects', workspace.id] }); client.invalidateQueries({ queryKey: ['flows', workspace.id] }); };
  const add = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/${subject}/${subjectId}/labels/${labelId}`, mutation('POST')), onSuccess: () => { setLabelId(''); changed(); } });
  const remove = useMutation({ mutationFn: (id: string) => api(`/workspaces/${workspace.id}/${subject}/${subjectId}/labels/${id}`, mutation('DELETE')), onSuccess: changed });
  const selected = new Set(assigned.map((label) => label.id));
  return <section><h3>Labels</h3>{assigned.map((label) => <span className="chip removable" key={label.id}><span className="label-dot" style={{ background: label.color }} />{label.name}<button aria-label={`Remove ${label.name}`} onClick={() => remove.mutate(label.id)}>×</button></span>)}{!assigned.length && <p className="muted">No labels applied.</p>}<div className="inline-fields"><select value={labelId} onChange={(event) => setLabelId(event.target.value)}><option value="">Add label…</option>{labels.data?.filter((label) => !selected.has(label.id)).map((label) => <option key={label.id} value={label.id}>{label.name}</option>)}</select><button className="button" onClick={() => add.mutate()} disabled={!labelId || add.isPending}>Add</button></div></section>;
}

function RelationEditor({ workspace, kind, subjectId, relations }: { workspace: Workspace; kind: 'task' | 'flow'; subjectId: string; relations: any[] }) {
  const client = useQueryClient(); const [targetId, setTargetId] = useState(''); const [type, setType] = useState(kind === 'task' ? 'blocks' : 'blocks'); const [explanation, setExplanation] = useState('');
  const targets = useQuery<ApiPage<any>>({ queryKey: [`${kind}-relation-options`, workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/${kind === 'task' ? 'tasks' : 'flows'}?limit=100`) });
  const refresh = () => client.invalidateQueries({ queryKey: [kind, workspace.id, subjectId] });
  const add = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/${kind}/relations`, mutation('POST', { sourceId: subjectId, targetId, type, explanation })), onSuccess: () => { setTargetId(''); setExplanation(''); refresh(); } });
  const remove = useMutation({ mutationFn: (relationId: string) => api(`/workspaces/${workspace.id}/${kind}/relations/${relationId}`, mutation('DELETE')), onSuccess: refresh });
  const choices = targets.data?.items.map((entry) => kind === 'task' ? { id: entry.task.id, name: entry.task.title } : { id: entry.flow.id, name: entry.flow.name }) ?? [];
  const typeOptions = kind === 'task' ? ['blocks', 'related', 'duplicate_of'] : ['blocks', 'related', 'replaces', 'merged_into'];
  const display = (relation: any) => { const source = kind === 'task' ? relation.sourceTaskId : relation.sourceFlowId; const target = kind === 'task' ? relation.targetTaskId : relation.targetFlowId; if (source === subjectId) return `${relation.type.replaceAll('_', ' ')} ${shortId(target)}`; if (relation.type === 'blocks') return `blocked by ${shortId(source)}`; return `${relation.type.replaceAll('_', ' ')} ${shortId(source)}`; };
  return <section><h3>Relations and dependencies</h3>{relations.length ? relations.map((relation) => <div className="relation-row" key={relation.id}><span>{display(relation)}{relation.explanation ? ` — ${relation.explanation}` : ''}</span><button className="text-button" aria-label="Remove relation" onClick={() => remove.mutate(relation.id)}>Remove</button></div>) : <p className="muted">No relations recorded.</p>}<div className="relation-form"><select value={type} onChange={(event) => setType(event.target.value)}>{typeOptions.map((option) => <option key={option} value={option}>{option.replaceAll('_', ' ')}</option>)}</select><select value={targetId} onChange={(event) => setTargetId(event.target.value)}><option value="">Select {kind}…</option>{choices.filter((choice) => choice.id !== subjectId).map((choice) => <option key={choice.id} value={choice.id}>{choice.name}</option>)}</select><input value={explanation} onChange={(event) => setExplanation(event.target.value)} placeholder="Optional explanation" /><button className="button" disabled={!targetId || add.isPending} onClick={() => add.mutate()}>Link</button></div><Error text={add.error instanceof Error ? add.error.message : ''} /></section>;
}

function TaskProperties({ workspace, task, save }: { workspace: Workspace; task: any; save: (body: any) => void }) {
  const projects = useQuery<ApiPage<Project>>({ queryKey: ['project-options', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/projects?limit=100`) }); const flows = useQuery<ApiPage<any>>({ queryKey: ['flow-options', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/flows?limit=100`) }); const members = useQuery<any[]>({ queryKey: ['members', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/members`) });
  const primaryFlowId = task.flows?.find((entry: any) => entry.link.role === 'primary')?.flow.id ?? ''; const relatedFlowIds = task.flows?.filter((entry: any) => entry.link.role === 'related').map((entry: any) => entry.flow.id) ?? [];
  return <details className="properties"><summary>Manage task</summary><form className="property-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); save({ title: form.get('title'), projectId: form.get('projectId'), priority: form.get('priority'), assigneeMembershipId: form.get('assigneeMembershipId') || null, dueDate: form.get('dueDate') || null, humanReviewRequired: form.get('humanReviewRequired') === 'on', reviewerMembershipId: form.get('reviewerMembershipId') || null, primaryFlowId: form.get('primaryFlowId') || null, relatedFlowIds: Array.from((event.currentTarget.elements.namedItem('relatedFlowIds') as HTMLSelectElement).selectedOptions).map((option) => option.value) }); }}><Field label="Title" name="title" defaultValue={task.title} required /><label>Project<select name="projectId" defaultValue={task.projectId}>{projects.data?.items.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Priority<select name="priority" defaultValue={task.priority}>{priorityOptions()}</select></label><label>Assignee<select name="assigneeMembershipId" defaultValue={task.assigneeMembershipId ?? ''}><option value="">Unassigned</option>{members.data?.filter((member) => member.active).map((member) => <option key={member.id} value={member.id}>{member.displayName}</option>)}</select></label><Field label="Due date" name="dueDate" type="date" defaultValue={task.dueDate ?? ''} /><label className="check"><input name="humanReviewRequired" type="checkbox" defaultChecked={task.humanReviewRequired} />Human review required</label><label>Reviewer<select name="reviewerMembershipId" defaultValue={task.reviewerMembershipId ?? ''}><option value="">No reviewer</option>{members.data?.filter((member) => member.active).map((member) => <option key={member.id} value={member.id}>{member.displayName}</option>)}</select></label><label>Primary flow<select name="primaryFlowId" defaultValue={primaryFlowId}><option value="">No primary flow</option>{flows.data?.items.map(({ flow }) => <option key={flow.id} value={flow.id}>{flow.name}</option>)}</select></label><label>Related flows<select name="relatedFlowIds" multiple defaultValue={relatedFlowIds}>{flows.data?.items.map(({ flow }) => <option key={flow.id} value={flow.id}>{flow.name}</option>)}</select></label><button className="button primary" type="submit">Save task details</button></form></details>;
}

function FlowProperties({ workspace, flow, save }: { workspace: Workspace; flow: any; save: (body: any) => void }) {
  const projects = useQuery<ApiPage<Project>>({ queryKey: ['project-options', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/projects?limit=100`) }); const members = useQuery<any[]>({ queryKey: ['members', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/members`) });
  return <details className="properties"><summary>Manage flow</summary><form className="property-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); save({ name: form.get('name'), priority: form.get('priority'), health: form.get('health'), responsibleMembershipId: form.get('responsibleMembershipId') || null, primaryCurrentTaskId: form.get('primaryCurrentTaskId') || null, scope: form.get('scope'), allowedProjectIds: Array.from((event.currentTarget.elements.namedItem('allowedProjectIds') as HTMLSelectElement).selectedOptions).map((option) => option.value) }); }}><Field label="Name" name="name" defaultValue={flow.name} required /><label>Priority<select name="priority" defaultValue={flow.priority}>{priorityOptions()}</select></label><label>Health<select name="health" defaultValue={flow.health}>{healthOptions()}</select></label><label>Responsible member<select name="responsibleMembershipId" defaultValue={flow.responsibleMembershipId ?? ''}><option value="">No responsible member</option>{members.data?.filter((member) => member.active).map((member) => <option key={member.id} value={member.id}>{member.displayName}</option>)}</select></label><label>Primary current task<select name="primaryCurrentTaskId" defaultValue={flow.primaryCurrentTaskId ?? ''}><option value="">No primary task</option>{flow.tasks?.map((entry: any) => <option key={entry.task.id} value={entry.task.id}>{entry.task.title}</option>)}</select></label><label>Project scope<select name="scope" defaultValue={flow.scope}><option value="all_projects">All projects</option><option value="selected_projects">Selected projects</option></select></label><label>Allowed projects<select name="allowedProjectIds" multiple defaultValue={flow.allowedProjects?.map((project: Project) => project.id) ?? []}>{projects.data?.items.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><button className="button primary" type="submit">Save flow details</button></form></details>;
}

function ProjectsPage({ workspace }: { workspace: Workspace }) {
  const { projectId } = useParams(); const navigate = useNavigate(); const [filters, setFilters] = useState({ q: '', status: '', priority: '', health: '' }); const projects = useCursorList<Project>(['projects', workspace.id], `/workspaces/${workspace.id}/projects`, filters);
  const setFilter = (name: keyof typeof filters, value: string) => setFilters((current) => ({ ...current, [name]: value }));
  return <Page heading="Projects" subheading="Stable technical ownership boundaries." action={<CreateProject workspace={workspace} />}><div className="content-grid"><section className="list-panel"><input className="search" placeholder="Search projects" value={filters.q} onChange={(event) => setFilter('q', event.target.value)} /><div className="filter-grid compact"><select aria-label="Filter project status" value={filters.status} onChange={(event) => setFilter('status', event.target.value)}><option value="">All statuses</option>{['proposed', 'planned', 'active', 'paused', 'completed', 'archived'].map((status) => <option key={status} value={status}>{status}</option>)}</select><select aria-label="Filter project priority" value={filters.priority} onChange={(event) => setFilter('priority', event.target.value)}><option value="">All priorities</option>{priorityOptions()}</select><select aria-label="Filter project health" value={filters.health} onChange={(event) => setFilter('health', event.target.value)}><option value="">All health</option>{healthOptions()}</select></div><div className="table-list">{projects.items.map((project) => <button key={project.id} onClick={() => navigate(`/w/${workspace.id}/projects/${project.id}`)} className={`row-button ${projectId === project.id ? 'selected' : ''}`}><span className="project-mark">P</span><span className="row-main"><strong>{project.name}</strong><small>{project.status} · {project.health.replace('_', ' ')}</small></span><time>{relativeTime(project.updatedAt)}</time></button>)}</div>{!projects.items.length && !projects.isLoading && <Empty title="No matching projects" text="Adjust filters or create a technical home for work." />}{projects.hasNextPage && <button className="button load-more" onClick={() => projects.fetchNextPage()} disabled={projects.isFetchingNextPage}>{projects.isFetchingNextPage ? 'Loading…' : 'Load more'}</button>}</section><section className="detail-panel">{projectId ? <ProjectDetail workspace={workspace} projectId={projectId} /> : <Hint title="Choose a project" text="Projects stay stable even as priorities and flows change." />}</section></div></Page>;
}

function CreateProject({ workspace }: { workspace: Workspace }) {
  const client = useQueryClient(); const [open, setOpen] = useState(false); const [name, setName] = useState('');
  const create = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/projects`, mutation('POST', { name })), onSuccess: () => { client.invalidateQueries({ queryKey: ['projects', workspace.id] }); setOpen(false); setName(''); } });
  return open ? <InlineForm onCancel={() => setOpen(false)} onSubmit={() => create.mutate()} pending={create.isPending}><Field label="Project name" value={name} onChange={setName} autoFocus /></InlineForm> : <button className="button primary" onClick={() => setOpen(true)}>New project</button>;
}

function ProjectDetail({ workspace, projectId }: { workspace: Workspace; projectId: string }) {
  const client = useQueryClient(); const detail = useQuery<any>({ queryKey: ['project', workspace.id, projectId], queryFn: () => api(`/workspaces/${workspace.id}/projects/${projectId}`) });
  const update = useMutation({ mutationFn: (body: any) => api(`/workspaces/${workspace.id}/projects/${projectId}`, mutation('PATCH', body, detail.data.version)), onSuccess: () => { client.invalidateQueries({ queryKey: ['project', workspace.id, projectId] }); client.invalidateQueries({ queryKey: ['projects', workspace.id] }); } });
  if (detail.isLoading) return <Loading />; if (!detail.data) return <Empty title="Project not found" text="It may have been deleted." />; const project = detail.data;
  return <article className="detail"><header className="detail-header"><div><span className="eyebrow">Technical ownership</span><h2>{project.name}</h2></div><select value={project.status} onChange={(event) => update.mutate({ status: event.target.value })}>{['proposed', 'planned', 'active', 'paused', 'completed', 'archived'].map((status) => <option key={status}>{status}</option>)}</select></header><EditableMarkdown title="Purpose" value={project.description} onSave={(description) => update.mutate({ description })} /><section className="meta-grid"><label>Priority<select value={project.priority} onChange={(event) => update.mutate({ priority: event.target.value })}>{priorityOptions()}</select></label><label>Health<select value={project.health} onChange={(event) => update.mutate({ health: event.target.value })}>{healthOptions()}</select></label></section><EditableMarkdown title="Current focus" value={project.currentFocus} onSave={(currentFocus) => update.mutate({ currentFocus })} /><EditableMarkdown title="Current-state summary" value={project.currentStateSummary} empty="Summarize the current technical state." onSave={(currentStateSummary) => update.mutate({ currentStateSummary })} /><EditableMarkdown title="Repository reference" value={project.repositoryReference} empty="Record a repository reference when useful." onSave={(repositoryReference) => update.mutate({ repositoryReference })} /><LabelEditor workspace={workspace} subject="project" subjectId={project.id} assigned={project.labels ?? []} /><section><h3>Work in this project</h3>{project.tasks?.length ? project.tasks.slice(0, 12).map((task: Task) => <p key={task.id} className="linked-row">{task.title}</p>) : <p className="muted">No active tasks.</p>}</section><section><h3>Flows involving this project</h3>{project.flows?.length ? project.flows.map((flow: Flow) => <span className="chip" key={flow.id}>{flow.name}</span>) : <p className="muted">No connected flows.</p>}</section><Activity events={project.activity ?? []} /></article>;
}

function FlowsPage({ workspace }: { workspace: Workspace }) {
  const { flowId } = useParams(); const navigate = useNavigate(); const [filters, setFilters] = useState({ q: '', stateId: '', priority: '', health: '' }); const flows = useCursorList<any>(['flows', workspace.id], `/workspaces/${workspace.id}/flows`, filters); const states = useQuery<WorkflowState[]>({ queryKey: ['states', workspace.id, 'flow'], queryFn: () => api(`/workspaces/${workspace.id}/workflows?entity=flow`) });
  const setFilter = (name: keyof typeof filters, value: string) => setFilters((current) => ({ ...current, [name]: value }));
  return <Page heading="Flows" subheading="Persistent continuity of purpose across projects." action={<CreateFlow workspace={workspace} states={states.data ?? []} />}><div className="content-grid"><section className="list-panel"><input className="search" placeholder="Search flows" value={filters.q} onChange={(event) => setFilter('q', event.target.value)} /><div className="filter-grid compact"><select aria-label="Filter flow state" value={filters.stateId} onChange={(event) => setFilter('stateId', event.target.value)}><option value="">All states</option>{states.data?.map((state) => <option key={state.id} value={state.id}>{state.name}</option>)}</select><select aria-label="Filter flow priority" value={filters.priority} onChange={(event) => setFilter('priority', event.target.value)}><option value="">All priorities</option>{priorityOptions()}</select><select aria-label="Filter flow health" value={filters.health} onChange={(event) => setFilter('health', event.target.value)}><option value="">All health</option>{healthOptions()}</select></div><div className="table-list">{flows.items.map(({ flow, state }) => <button key={flow.id} onClick={() => navigate(`/w/${workspace.id}/flows/${flow.id}`)} className={`row-button ${flowId === flow.id ? 'selected' : ''}`}><Status state={state} /><span className="row-main"><strong>{flow.name}</strong><small>{state.name} · {flow.health.replace('_', ' ')}</small></span><time>{relativeTime(flow.updatedAt)}</time></button>)}</div>{!flows.items.length && !flows.isLoading && <Empty title="No matching flows" text="Adjust filters or define a direction of work." />}{flows.hasNextPage && <button className="button load-more" onClick={() => flows.fetchNextPage()} disabled={flows.isFetchingNextPage}>{flows.isFetchingNextPage ? 'Loading…' : 'Load more'}</button>}</section><section className="detail-panel">{flowId ? <FlowDetail workspace={workspace} flowId={flowId} states={states.data ?? []} /> : <Hint title="Choose a flow" text="Flows make strategic intent visible across project boundaries." />}</section></div></Page>;
}

function CreateFlow({ workspace, states }: { workspace: Workspace; states: WorkflowState[] }) {
  const client = useQueryClient(); const [open, setOpen] = useState(false); const [name, setName] = useState('');
  const create = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/flows`, mutation('POST', { name, workflowStateId: states.find((state) => state.isInitial)?.id })), onSuccess: () => { client.invalidateQueries({ queryKey: ['flows', workspace.id] }); setOpen(false); setName(''); } });
  return open ? <InlineForm onCancel={() => setOpen(false)} onSubmit={() => create.mutate()} pending={create.isPending}><Field label="Flow name" value={name} onChange={setName} autoFocus /></InlineForm> : <button className="button primary" onClick={() => setOpen(true)}>New flow</button>;
}

function FlowDetail({ workspace, flowId, states }: { workspace: Workspace; flowId: string; states: WorkflowState[] }) {
  const client = useQueryClient(); const detail = useQuery<any>({ queryKey: ['flow', workspace.id, flowId], queryFn: () => api(`/workspaces/${workspace.id}/flows/${flowId}`), refetchInterval: 15_000 }); const [criterion, setCriterion] = useState(''); const [comment, setComment] = useState('');
  const refresh = () => { client.invalidateQueries({ queryKey: ['flow', workspace.id, flowId] }); client.invalidateQueries({ queryKey: ['flows', workspace.id] }); };
  const update = useMutation({ mutationFn: (body: any) => api(`/workspaces/${workspace.id}/flows/${flowId}`, mutation('PATCH', body, detail.data.version)), onSuccess: refresh });
  const addCriterion = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/flows/${flowId}/criteria`, mutation('POST', { text: criterion })), onSuccess: () => { setCriterion(''); refresh(); } });
  const updateCriterion = useMutation({ mutationFn: (item: any) => api(`/workspaces/${workspace.id}/criteria/${item.id}`, mutation('PATCH', { completed: !item.completed })), onSuccess: refresh });
  const commentAction = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/flow/${flowId}/comments`, mutation('POST', { body: comment })), onSuccess: () => { setComment(''); refresh(); } });
  if (detail.isLoading) return <Loading />; if (!detail.data) return <Empty title="Flow not found" text="It may have been deleted." />; const flow = detail.data;
  const chooseState = async (workflowStateId: string) => { const preview = await api<{ warnings: string[] }>(`/workspaces/${workspace.id}/flows/${flowId}/transition-preview?stateId=${workflowStateId}`); if (!preview.warnings.length || window.confirm(`This transition has advisory signals:\n\n${preview.warnings.join('\n')}\n\nContinue?`)) update.mutate({ workflowStateId }); };
  return <article className="detail"><header className="detail-header"><div><span className="eyebrow">Continuity of purpose</span><h2>{flow.name}</h2></div><select value={flow.workflowStateId} onChange={(event) => void chooseState(event.target.value)}>{states.map((state) => <option key={state.id} value={state.id}>{state.name}</option>)}</select></header>{flow.signals?.transitionWarnings?.length > 0 && <Callout title="Convergence signals">{flow.signals.transitionWarnings.map((warning: string) => <p key={warning}>{warning}</p>)}</Callout>}<EditableMarkdown title="Purpose" value={flow.purpose} onSave={(purpose) => update.mutate({ purpose })} /><FlowProperties workspace={workspace} flow={flow} save={(body) => update.mutate(body)} /><section><h3>Convergence criteria <small>{flow.signals?.criteria?.completed ?? 0}/{flow.signals?.criteria?.total ?? 0}</small></h3>{flow.criteria?.map((item: any) => <label className="check" key={item.id}><input type="checkbox" checked={item.completed} onChange={() => updateCriterion.mutate(item)} />{item.text}</label>)}<div className="inline-fields"><input value={criterion} onChange={(event) => setCriterion(event.target.value)} placeholder="Add convergence criterion" /><button className="button" onClick={() => addCriterion.mutate()} disabled={!criterion.trim()}>Add</button></div></section><EditableMarkdown title="Current focus" value={flow.currentFocus} onSave={(currentFocus) => update.mutate({ currentFocus })} /><EditableMarkdown title="Important findings" value={flow.importantFindings} empty="Record the key evidence and findings." onSave={(importantFindings) => update.mutate({ importantFindings })} /><EditableMarkdown title="Next recommended action" value={flow.nextRecommendedAction} onSave={(nextRecommendedAction) => update.mutate({ nextRecommendedAction })} /><section><h3>Participating projects</h3>{flow.participatingProjects?.length ? flow.participatingProjects.map((project: Project) => <span className="chip" key={project.id}>{project.name}</span>) : <p className="muted">Tasks will derive participating projects.</p>}</section><section><h3>Tasks by project</h3>{flow.tasks?.length ? flow.tasks.map((entry: any) => <p className="linked-row" key={entry.task.id}><span className="chip">{entry.project.name}</span> {entry.task.title}</p>) : <p className="muted">No linked tasks.</p>}</section><LabelEditor workspace={workspace} subject="flow" subjectId={flow.id} assigned={flow.labels ?? []} /><RelationEditor workspace={workspace} kind="flow" subjectId={flow.id} relations={flow.relations ?? []} /><section><h3>Discussion</h3><div className="comments">{flow.comments?.map((entry: any) => <article key={entry.id} className="comment"><Markdown value={entry.body} /><small>{relativeTime(entry.createdAt)}</small></article>)}</div><textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Add a finding, decision, or question…" /><button className="button" disabled={!comment.trim() || commentAction.isPending} onClick={() => commentAction.mutate()}>Add comment</button></section><Activity events={flow.activity ?? []} /></article>;
}

function TaskGitHub({ workspace, task }: { workspace: Workspace; task: any }) {
  const client = useQueryClient(); const [repositoryId, setRepositoryId] = useState(''); const [branch, setBranch] = useState('');
  const connection = useQuery<any>({ queryKey: ['github', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/github`), retry: false });
  const branchAction = useMutation({ mutationFn: () => api<{ branch: string }>(`/workspaces/${workspace.id}/github/tasks/${task.identifier}/branch`), onSuccess: async (result) => { setBranch(result.branch); await navigator.clipboard?.writeText(result.branch); } });
  const createIssue = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/github/tasks/${task.identifier}/issues`, mutation('POST', { repositoryId, syncMode: 'manual' })), onSuccess: () => client.invalidateQueries({ queryKey: ['task', workspace.id, task.identifier] }) });
  const repositories = connection.data?.repositories ?? [];
  useEffect(() => { if (!repositoryId && repositories[0]) setRepositoryId(repositories[0].id); }, [repositoryId, repositories]);
  return <section className="github-card"><header className="section-header"><h3>GitHub</h3><span className="chip">{connection.data?.connection?.status ?? (connection.data?.enabled === false ? 'disabled' : 'not connected')}</span></header><div className="inline-fields"><button className="button" onClick={() => branchAction.mutate()} disabled={!connection.data?.connection}>Copy branch name</button>{branch && <code>{branch}</code>}</div>{task.githubIssues?.length ? <div className="github-links">{task.githubIssues.map((issue: any) => <a key={issue.id} href={issue.htmlUrl} target="_blank" rel="noreferrer">Issue #{issue.issueNumber} · {issue.syncStatus}</a>)}</div> : connection.data?.connection ? <div className="inline-fields"><select value={repositoryId} onChange={(event) => setRepositoryId(event.target.value)}><option value="">Choose repository…</option>{repositories.map((repository: any) => <option key={repository.id} value={repository.id}>{repository.fullName}</option>)}</select><button className="button" disabled={!repositoryId || createIssue.isPending} onClick={() => createIssue.mutate()}>Create GitHub issue</button></div> : <p className="muted">Connect GitHub in workspace settings to copy a branch name, link issues, and track pull requests.</p>}<Error text={branchAction.error instanceof Error ? branchAction.error.message : createIssue.error instanceof Error ? createIssue.error.message : ''} />{task.githubPullRequests?.length ? <div className="github-links">{task.githubPullRequests.map((entry: any) => <a key={entry.id} href={entry.pullRequest.htmlUrl} target="_blank" rel="noreferrer">PR #{entry.pullRequest.number} · {entry.pullRequest.state}</a>)}</div> : null}</section>;
}

function ReviewsPage({ workspace }: { workspace: Workspace }) {
  const { pullRequestId } = useParams(); const navigate = useNavigate(); const [mode, setMode] = useState<'for-me' | 'created'>('for-me'); const [comment, setComment] = useState('');
  const reviews = useQuery<any[]>({ queryKey: ['github-reviews', workspace.id, mode], queryFn: () => api(`/workspaces/${workspace.id}/github/reviews?mode=${mode}`), refetchInterval: 15_000 });
  const detail = useQuery<any>({ queryKey: ['github-review', workspace.id, pullRequestId], queryFn: () => api(`/workspaces/${workspace.id}/github/reviews/${pullRequestId}`), enabled: Boolean(pullRequestId) });
  const diff = useQuery<any>({ queryKey: ['github-diff', workspace.id, pullRequestId], queryFn: () => api(`/workspaces/${workspace.id}/github/reviews/${pullRequestId}/diff`), enabled: Boolean(pullRequestId) });
  const review = useMutation({ mutationFn: (event: 'APPROVE' | 'REQUEST_CHANGES' | 'COMMENT') => api(`/workspaces/${workspace.id}/github/reviews/${pullRequestId}/reviews`, mutation('POST', { event })), onSuccess: () => detail.refetch() });
  const merge = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/github/reviews/${pullRequestId}/merge`, mutation('POST', { method: 'squash' })), onSuccess: () => detail.refetch() });
  const commentAction = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/github/reviews/${pullRequestId}/comments`, mutation('POST', { body: comment })), onSuccess: () => { setComment(''); detail.refetch(); } });
  const ready = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/github/reviews/${pullRequestId}/ready`, mutation('POST')), onSuccess: () => detail.refetch() });
  return <Page heading="Reviews" subheading="GitHub pull requests connected to this workspace."><div className="content-grid"><section className="list-panel"><div className="inline-fields"><button className={`button ${mode === 'for-me' ? 'primary' : ''}`} onClick={() => setMode('for-me')}>For me</button><button className={`button ${mode === 'created' ? 'primary' : ''}`} onClick={() => setMode('created')}>Created</button></div>{reviews.isLoading ? <Loading /> : <div className="table-list">{reviews.data?.map((pullRequest) => <button key={pullRequest.id} className={`row-button ${pullRequestId === pullRequest.id ? 'selected' : ''}`} onClick={() => navigate(`/w/${workspace.id}/reviews/${pullRequest.id}`)}><span className="project-mark">↗</span><span className="row-main"><strong>#{pullRequest.number} {pullRequest.title}</strong><small>{pullRequest.repository?.fullName} · {pullRequest.state}{pullRequest.draft ? ' · draft' : ''}</small></span></button>)}</div>}{!reviews.data?.length && !reviews.isLoading && <Empty title="No pull requests" text="Connect a GitHub App and select repositories in Settings." />}</section><section className="detail-panel">{!pullRequestId ? <Hint title="Choose a pull request" text="Open a review to inspect checks and diffs." /> : detail.isLoading ? <Loading /> : !detail.data ? <Empty title="Pull request unavailable" text="It may no longer be installed or accessible." /> : <article className="detail"><header className="detail-header"><div><span className="eyebrow">{detail.data.repository?.fullName} · #{detail.data.number}</span><h2>{detail.data.title}</h2></div><a className="button" href={detail.data.htmlUrl} target="_blank" rel="noreferrer">Open GitHub</a></header><section><h3>Review status</h3><p className="muted">{detail.data.state} · {detail.data.reviewDecision ?? 'awaiting review'} · {detail.data.mergeableState ?? 'mergeability pending'}</p><div className="inline-fields"><button className="button" onClick={() => review.mutate('APPROVE')}>Approve</button><button className="button" onClick={() => review.mutate('REQUEST_CHANGES')}>Request changes</button>{detail.data.draft && <button className="button" onClick={() => ready.mutate()} disabled={ready.isPending}>Mark ready</button>}<button className="button primary" onClick={() => window.confirm('Merge this pull request with squash?') && merge.mutate()}>Squash merge</button></div><textarea value={comment} onChange={(event) => setComment(event.target.value)} placeholder="Leave a top-level pull request comment…" /><button className="button" disabled={!comment.trim() || commentAction.isPending} onClick={() => commentAction.mutate()}>Post comment</button><Error text={review.error instanceof Error ? review.error.message : merge.error instanceof Error ? merge.error.message : ready.error instanceof Error ? ready.error.message : commentAction.error instanceof Error ? commentAction.error.message : ''} /></section><section><h3>Linked tasks</h3>{detail.data.tasks?.length ? detail.data.tasks.map((entry: any) => <span className="chip" key={entry.task.id}>{entry.task.identifier} · {entry.task.title}</span>) : <p className="muted">No Anklav task is linked yet.</p>}</section><section><h3>Checks</h3>{detail.data.checks?.length ? detail.data.checks.map((check: any, index: number) => <p className="linked-row" key={index}>{String(check.name ?? check.context ?? 'Check')} · {String(check.conclusion ?? check.status ?? 'pending')}</p>) : <p className="muted">No check summary received yet.</p>}</section><section><h3>Diff</h3>{diff.isLoading ? <p className="muted">Loading from GitHub…</p> : diff.error ? <Callout title="Diff unavailable"><p>Open the pull request in GitHub for large or unavailable files.</p></Callout> : <pre className="github-diff">{diff.data?.diff}</pre>}</section></article>}</section></div></Page>;
}

function InboxPage({ workspace }: { workspace: Workspace }) {
  const client = useQueryClient(); const notifications = useQuery<any[]>({ queryKey: ['github-notifications', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/github/notifications`), refetchInterval: 15_000 });
  const read = useMutation({ mutationFn: (id: string) => api(`/workspaces/${workspace.id}/github/notifications/${id}/read`, mutation('PATCH')), onSuccess: () => { client.invalidateQueries({ queryKey: ['github-notifications', workspace.id] }); client.invalidateQueries({ queryKey: ['github-notification-count', workspace.id] }); } });
  return <Page heading="Inbox" subheading="Review requests, comments, checks, and merge activity."><section className="settings-card">{notifications.isLoading ? <Loading /> : notifications.data?.length ? notifications.data.map((notification) => <button key={notification.id} className="notification-row" onClick={() => { read.mutate(notification.id); if (notification.href) window.location.assign(notification.href); }}><span><strong>{notification.title}</strong><small>{notification.body || relativeTime(notification.createdAt)}</small></span>{!notification.readAt && <span className="status-dot" />}</button>) : <Empty title="You’re all caught up" text="GitHub review activity will appear here after a connection is enabled." />}</section></Page>;
}

function GitHubSettings({ workspace }: { workspace: Workspace }) {
  const client = useQueryClient(); const connection = useQuery<any>({ queryKey: ['github', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/github`), retry: false }); const projects = useQuery<ApiPage<Project>>({ queryKey: ['github-projects', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/projects?limit=100`) });
  const [organizationLogin, setOrganizationLogin] = useState(''); const [repositoryId, setRepositoryId] = useState(''); const [projectId, setProjectId] = useState(''); const [syncMode, setSyncMode] = useState('none');
  const connect = useMutation({ mutationFn: () => api<{ redirectUrl: string }>(`/workspaces/${workspace.id}/github/manifest`, mutation('POST', { organizationLogin })), onSuccess: ({ redirectUrl }) => window.location.assign(redirectUrl) });
  const account = useMutation({ mutationFn: () => api<{ redirectUrl: string }>(`/workspaces/${workspace.id}/github/account`, mutation('POST')), onSuccess: ({ redirectUrl }) => window.location.assign(redirectUrl) });
  const map = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/github/repositories/mappings`, mutation('POST', { repositoryId, projectId, syncMode, defaultInbound: syncMode !== 'none', defaultOutbound: syncMode === 'bidirectional' })), onSuccess: () => client.invalidateQueries({ queryKey: ['github', workspace.id] }) });
  if (connection.isLoading) return <section className="settings-card"><h2>GitHub</h2><p className="muted">Loading connection status…</p></section>;
  if (connection.data?.enabled === false) return <section className="settings-card"><h2>GitHub</h2><p className="muted">GitHub integration is disabled by this instance. Set GITHUB_INTEGRATION_ENABLED=true, PUBLIC_BASE_URL, and INTEGRATION_ENCRYPTION_KEY to enable it.</p></section>;
  const repositories = connection.data?.repositories ?? [];
  return <section className="settings-card wide"><h2>GitHub</h2>{!connection.data?.connection ? <div className="stack"><p className="muted">Create a private GitHub App for one organization. Anklav will retain its credentials encrypted in this workspace database.</p><div className="inline-fields"><input value={organizationLogin} onChange={(event) => setOrganizationLogin(event.target.value)} placeholder="GitHub organization" /><button className="button primary" disabled={!organizationLogin.trim() || connect.isPending} onClick={() => connect.mutate()}>Create GitHub App</button></div><Error text={connect.error instanceof Error ? connect.error.message : ''} /></div> : <div className="stack"><p><span className="chip">{connection.data.connection.status}</span> {connection.data.connection.organizationLogin ?? 'Organization pending'}</p><div className="inline-fields"><button className="button" onClick={() => account.mutate()} disabled={account.isPending}>Connect my GitHub account</button></div>{repositories.length ? <form className="property-form" onSubmit={(event) => { event.preventDefault(); map.mutate(); }}><label>Repository<select value={repositoryId} onChange={(event) => setRepositoryId(event.target.value)} required><option value="">Choose…</option>{repositories.map((repository: any) => <option key={repository.id} value={repository.id}>{repository.fullName}</option>)}</select></label><label>Project<select value={projectId} onChange={(event) => setProjectId(event.target.value)} required><option value="">Choose…</option>{projects.data?.items.map((project) => <option key={project.id} value={project.id}>{project.issueKey} · {project.name}</option>)}</select></label><label>Issue sync<select value={syncMode} onChange={(event) => setSyncMode(event.target.value)}><option value="none">PR linking only</option><option value="inbound">GitHub → Anklav</option><option value="bidirectional">Two-way issue sync</option></select></label><button className="button primary" disabled={map.isPending}>Save mapping</button></form> : <p className="muted">Install the GitHub App to load its selected repositories.</p>}<Error text={account.error instanceof Error ? account.error.message : map.error instanceof Error ? map.error.message : ''} /></div>}</section>;
}

function SearchPage({ workspace }: { workspace: Workspace }) {
  const navigate = useNavigate(); const [q, setQ] = useState('');
  const results = useQuery<any>({ queryKey: ['search', workspace.id, q], queryFn: () => api(`/workspaces/${workspace.id}/search?q=${encodeURIComponent(q)}`), enabled: q.trim().length > 1 });
  const groups = results.data ? [['tasks', 'Tasks'], ['projects', 'Projects'], ['flows', 'Flows']] as const : [];
  return <Page heading="Search" subheading="Find work across projects, flows, and tasks."><section className="search-surface"><input className="search large" autoFocus placeholder="Search titles and Markdown content" value={q} onChange={(event) => setQ(event.target.value)} />{q.trim().length < 2 ? <Hint title="Search your control room" text="Enter at least two characters to search all core work records." /> : results.isLoading ? <Loading /> : <div className="search-results">{groups.map(([key, title]) => <section key={key}><h2>{title}</h2>{results.data[key]?.length ? results.data[key].map((entry: any) => <button className="search-result" key={entry.id} onClick={() => navigate(`/w/${workspace.id}/${key}/${entry.id}`)}><span className="chip">{entry.kind}</span><strong>{entry.name}</strong></button>) : <p className="muted">No matches.</p>}</section>)}</div>}</section></Page>;
}

function SettingsPage({ workspace, session }: { workspace: Workspace; session: Session }) {
  const states = useQuery<WorkflowState[]>({ queryKey: ['states', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/workflows`) }); const labels = useQuery<any[]>({ queryKey: ['labels', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/labels`) }); const members = useQuery<any[]>({ queryKey: ['members', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/members`) }); const availableUsers = useQuery<any[]>({ queryKey: ['available-users', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/available-users`), enabled: workspace.role === 'owner' || workspace.role === 'admin' }); const trash = useQuery<any>({ queryKey: ['trash', workspace.id], queryFn: () => api(`/workspaces/${workspace.id}/trash`) }); const client = useQueryClient(); const [labelName, setLabelName] = useState(''); const [newState, setNewState] = useState({ entityType: 'task', name: '', semantic: 'planned', color: '#64748b' }); const [replacements, setReplacements] = useState<Record<string, string>>({});
  const canAdmin = workspace.role === 'owner' || workspace.role === 'admin';
  const refreshSettings = () => { client.invalidateQueries({ queryKey: ['states', workspace.id] }); client.invalidateQueries({ queryKey: ['labels', workspace.id] }); client.invalidateQueries({ queryKey: ['members', workspace.id] }); client.invalidateQueries({ queryKey: ['trash', workspace.id] }); };
  const addLabel = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/labels`, mutation('POST', { name: labelName })), onSuccess: () => { setLabelName(''); refreshSettings(); } });
  const updateLabel = useMutation({ mutationFn: ({ label, body }: any) => api(`/workspaces/${workspace.id}/labels/${label.id}`, mutation('PATCH', body, label.version)), onSuccess: refreshSettings });
  const deleteLabel = useMutation({ mutationFn: (label: any) => api(`/workspaces/${workspace.id}/label/${label.id}`, mutation('DELETE', undefined, label.version)), onSuccess: refreshSettings });
  const updateState = useMutation({ mutationFn: ({ state, body }: any) => api(`/workspaces/${workspace.id}/workflows/${state.id}`, mutation('PATCH', body, state.version)), onSuccess: refreshSettings });
  const archiveState = useMutation({ mutationFn: (state: WorkflowState) => api(`/workspaces/${workspace.id}/workflows/${state.id}/archive`, mutation('POST', { replacementStateId: replacements[state.id] }, state.version)), onSuccess: refreshSettings });
  const createState = useMutation({ mutationFn: () => api(`/workspaces/${workspace.id}/workflows/${newState.entityType}`, mutation('POST', newState)), onSuccess: () => { setNewState({ entityType: 'task', name: '', semantic: 'planned', color: '#64748b' }); refreshSettings(); } });
  const addMember = useMutation({ mutationFn: (body: any) => api(`/workspaces/${workspace.id}/members`, mutation('POST', body)), onSuccess: refreshSettings });
  const updateMember = useMutation({ mutationFn: ({ member, body }: any) => api(`/workspaces/${workspace.id}/members/${member.id}`, mutation('PATCH', body)), onSuccess: refreshSettings });
  const createAccount = useMutation({ mutationFn: (body: any) => api('/accounts', mutation('POST', body)), onSuccess: () => client.invalidateQueries({ queryKey: ['accounts'] }) });
  const restore = useMutation({ mutationFn: ({ kind, item }: any) => api(`/workspaces/${workspace.id}/${kind}/${item.id}/restore`, mutation('POST', undefined, item.version)), onSuccess: refreshSettings });
  const semantics = newState.entityType === 'task' ? ['inbox', 'planned', 'ready', 'in_progress', 'human_review', 'blocked', 'done', 'cancelled'] : ['proposed', 'active', 'paused', 'converged', 'closed'];
  return <Page heading="Settings" subheading="Workspace membership, workflows, labels, and recovery."><div className="settings-grid"><section className="settings-card wide"><h2>Workflow states</h2>{states.data?.map((state) => <div className="state-row" key={state.id}><Status state={state} /><input aria-label={`${state.name} name`} defaultValue={state.name} disabled={!canAdmin} onBlur={(event) => event.target.value !== state.name && updateState.mutate({ state, body: { name: event.target.value } })} /><input aria-label={`${state.name} color`} className="color-input" type="color" defaultValue={state.color} disabled={!canAdmin} onBlur={(event) => event.target.value !== state.color && updateState.mutate({ state, body: { color: event.target.value } })} /><span className="chip">{state.entityType} · {state.taskSemantic ?? state.flowSemantic}</span><button className="text-button" disabled={!canAdmin || state.position === 0} onClick={() => updateState.mutate({ state, body: { position: state.position - 1 } })}>↑</button><button className="text-button" disabled={!canAdmin} onClick={() => updateState.mutate({ state, body: { position: state.position + 1 } })}>↓</button><select aria-label={`Replacement for ${state.name}`} value={replacements[state.id] ?? ''} disabled={!canAdmin} onChange={(event) => setReplacements((current) => ({ ...current, [state.id]: event.target.value }))}><option value="">Replace with…</option>{states.data?.filter((candidate) => candidate.entityType === state.entityType && candidate.id !== state.id && !candidate.archivedAt).map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.name}</option>)}</select><button className="text-button danger" disabled={!canAdmin || !replacements[state.id]} onClick={() => archiveState.mutate(state)}>Archive</button></div>)}{canAdmin && <form className="add-row" onSubmit={(event) => { event.preventDefault(); createState.mutate(); }}><select value={newState.entityType} onChange={(event) => setNewState({ entityType: event.target.value, name: '', semantic: event.target.value === 'task' ? 'planned' : 'active', color: '#64748b' })}><option value="task">Task state</option><option value="flow">Flow state</option></select><input placeholder="State name" value={newState.name} onChange={(event) => setNewState((current) => ({ ...current, name: event.target.value }))} required /><select value={newState.semantic} onChange={(event) => setNewState((current) => ({ ...current, semantic: event.target.value }))}>{semantics.map((semantic) => <option key={semantic} value={semantic}>{semantic.replaceAll('_', ' ')}</option>)}</select><input className="color-input" type="color" value={newState.color} onChange={(event) => setNewState((current) => ({ ...current, color: event.target.value }))} /><button className="button" disabled={createState.isPending}>Add state</button></form>}<p className="muted">Semantic categories stay stable even as workspace vocabulary changes. Archiving atomically reassigns existing work.</p></section><section className="settings-card"><h2>Labels</h2>{labels.data?.map((label) => <div className="setting-row" key={label.id}><input className="color-input" type="color" defaultValue={label.color} disabled={!canAdmin} onBlur={(event) => event.target.value !== label.color && updateLabel.mutate({ label, body: { color: event.target.value } })} /><input aria-label={`${label.name} label`} defaultValue={label.name} disabled={!canAdmin} onBlur={(event) => event.target.value !== label.name && updateLabel.mutate({ label, body: { name: event.target.value } })} />{canAdmin && <button className="text-button danger" onClick={() => window.confirm(`Delete ${label.name}?`) && deleteLabel.mutate(label)}>Delete</button>}</div>)}{canAdmin && <div className="inline-fields"><input value={labelName} onChange={(event) => setLabelName(event.target.value)} placeholder="New label" /><button className="button" onClick={() => addLabel.mutate()} disabled={!labelName.trim()}>Add</button></div>}</section><section className="settings-card"><h2>Members</h2>{members.data?.map((member) => <div className="setting-row" key={member.id}><span><strong>{member.displayName}</strong><small>{member.email}</small></span>{canAdmin ? <select value={member.role} onChange={(event) => updateMember.mutate({ member, body: { role: event.target.value } })}><option value="owner">owner</option><option value="admin">admin</option><option value="member">member</option></select> : <span className="chip">{member.role}</span>}{canAdmin && <button className="text-button danger" disabled={!member.active} onClick={() => window.confirm(`Remove ${member.displayName} from this workspace?`) && updateMember.mutate({ member, body: { active: false } })}>Remove</button>}</div>)}{canAdmin && <form className="add-row" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); addMember.mutate({ userId: form.get('userId'), role: form.get('role') }); event.currentTarget.reset(); }}><select name="userId" required defaultValue=""><option value="" disabled>Add an account…</option>{availableUsers.data?.filter((account) => !members.data?.some((member) => member.userId === account.id && member.active)).map((account) => <option key={account.id} value={account.id}>{account.displayName} · {account.email}</option>)}</select><select name="role" defaultValue="member"><option value="member">member</option><option value="admin">admin</option><option value="owner">owner</option></select><button className="button">Add member</button></form>}</section><TrashSection workspace={workspace} trash={trash.data} restore={restore} /><ConnectedClients />{session.user.instanceRole === 'instance_admin' && <section className="settings-card"><h2>Instance accounts</h2><form className="property-form" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); createAccount.mutate({ email: form.get('email'), displayName: form.get('displayName'), password: form.get('password') }); event.currentTarget.reset(); }}><Field label="Name" name="displayName" required /><Field label="Email" name="email" type="email" required /><Field label="Temporary password" name="password" type="password" minLength={12} required /><button className="button primary">Create account</button></form></section>}</div></Page>;
}

function TrashSection({ workspace, trash, restore }: { workspace: Workspace; trash: any; restore: any }) {
  const entries = trash ? Object.entries(trash).flatMap(([kind, items]) => (items as any[]).map((item) => ({ kind: kind.replace(/s$/, ''), item }))) : [];
  return <section className="settings-card"><h2>Trash</h2>{entries.length ? <div className="trash-list">{entries.map(({ kind, item }) => <div className="setting-row" key={`${kind}-${item.id}`}><span><strong>{item.name ?? item.title ?? item.body?.slice(0, 48) ?? kind}</strong><small>{kind} · deleted {relativeTime(item.deletedAt)}</small></span><button className="button" disabled={restore.isPending} onClick={() => restore.mutate({ kind, item })}>Restore</button></div>)}</div> : <p className="muted">Nothing is currently deleted.</p>}</section>;
}

function ConnectedClients() {
  const client = useQueryClient(); const grants = useQuery<any[]>({ queryKey: ['oauth-grants'], queryFn: () => api('/oauth/grants') });
  const revoke = useMutation({ mutationFn: (grantId: string) => api(`/oauth/grants/${grantId}`, mutation('DELETE')), onSuccess: () => client.invalidateQueries({ queryKey: ['oauth-grants'] }) });
  return <section className="settings-card"><h2>Connected clients</h2>{grants.data?.length ? grants.data.map((grant) => <div className="setting-row" key={grant.id}><span><strong>{grant.client.name}</strong><small>{grant.scopes.join(', ')} · {grant.workspaceIds.length} workspace{grant.workspaceIds.length === 1 ? '' : 's'}</small></span><button className="text-button danger" disabled={revoke.isPending} onClick={() => window.confirm(`Revoke ${grant.client.name}?`) && revoke.mutate(grant.id)}>Revoke</button></div>) : <p className="muted">No MCP clients are connected.</p>}</section>;
}

function Page({ heading, subheading, action, children }: { heading: string; subheading: string; action?: ReactNode; children: ReactNode }) { return <div className="page"><header className="page-header"><div><span className="eyebrow">Anklav control room</span><h1>{heading}</h1><p>{subheading}</p></div><div className="page-action">{action}</div></header>{children}</div>; }
function Brand({ compact = false }: { compact?: boolean }) { return <div className={`brand ${compact ? 'compact' : ''}`}><span className="brand-mark">N</span>{!compact && <span>Anklav</span>}</div>; }
function Field({ label, name, type = 'text', value, onChange, ...props }: { label: string; name?: string; type?: string; value?: string; onChange?: (value: string) => void; [key: string]: any }) { return <label className="field"><span>{label}</span><input name={name} type={type} value={value} onChange={onChange ? (event) => onChange(event.target.value) : undefined} {...props} /></label>; }
function InlineForm({ children, onSubmit, onCancel, pending }: { children: ReactNode; onSubmit: () => void; onCancel: () => void; pending: boolean }) { return <form className="inline-form" onSubmit={(event) => { event.preventDefault(); onSubmit(); }}>{children}<div><button className="button primary" disabled={pending}>Create</button><button type="button" className="button ghost" onClick={onCancel}>Cancel</button></div></form>; }
function Status({ state }: { state: Partial<WorkflowState> }) { return <span className="status-dot" title={state.name} style={{ background: state.color ?? '#64748b' }} />; }
function Meta({ label, value }: { label: string; value: string }) { return <div><small>{label}</small><strong>{value}</strong></div>; }
function Callout({ title, children }: { title: string; children: ReactNode }) { return <aside className="callout"><strong>{title}</strong>{children}</aside>; }
function Activity({ events }: { events: any[] }) { return <section><h3>Activity</h3>{events.length ? <ol className="activity">{events.slice(0, 20).map((event) => <li key={event.id}><div><strong>{event.action.replaceAll('_', ' ')}</strong>{event.actorName && <span className="activity-actor">by {event.actorName}</span>}{Object.keys(event.after ?? {}).length > 0 && <small className="activity-change">{Object.entries(event.after).map(([key, value]) => `${humanize(key)}: ${String(value)}`).join(' · ')}</small>}</div><small>{relativeTime(event.createdAt)}</small></li>)}</ol> : <p className="muted">No activity recorded yet.</p>}</section>; }
function Markdown({ value }: { value: string }) { const html = useMemo(() => DOMPurify.sanitize(marked.parse(value || '') as string), [value]); return value ? <div className="markdown" dangerouslySetInnerHTML={{ __html: html }} /> : null; }
function EditableMarkdown({ title, value, empty = 'Add context.', onSave }: { title: string; value: string; empty?: string; onSave: (value: string) => void }) { const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(value); useEffect(() => setDraft(value), [value]); return <section><header className="section-header"><h3>{title}</h3><button className="text-button" onClick={() => editing ? (onSave(draft), setEditing(false)) : setEditing(true)}>{editing ? 'Save' : 'Edit'}</button></header>{editing ? <textarea autoFocus value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={empty} /> : <Markdown value={value} />}{!editing && !value && <p className="muted">{empty}</p>}</section>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty"><strong>{title}</strong><p>{text}</p></div>; }
function Hint({ title, text }: { title: string; text: string }) { return <div className="hint"><span>↗</span><h2>{title}</h2><p>{text}</p></div>; }
function Error({ text }: { text: string }) { return text ? <p className="error">{text}</p> : null; }
function Loading() { return <div className="loading"><span />Loading…</div>; }
function priorityOptions() { return ['none', 'low', 'medium', 'high', 'urgent'].map((value) => <option value={value} key={value}>{value}</option>); }
function healthOptions() { return ['unknown', 'on_track', 'at_risk', 'off_track'].map((value) => <option value={value} key={value}>{value.replace('_', ' ')}</option>); }
function shortId(value: string) { return value.slice(0, 8); }
function humanize(value: string) { return value.replace(/([A-Z])/g, ' $1').replaceAll('_', ' ').toLowerCase(); }
function relativeTime(value: string) { const seconds = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 1_000)); if (seconds < 60) return 'now'; if (seconds < 3_600) return `${Math.floor(seconds / 60)}m`; if (seconds < 86_400) return `${Math.floor(seconds / 3_600)}h`; return `${Math.floor(seconds / 86_400)}d`; }

export default App;
